use glam::DVec3 as V;
use ingetrazo_gui::IngeTrazoApp;
use ingetrazo_core::{image_plane::ImagePlane,scene::SelectionItem,math::Ray};
use ingetrazo_tools::base::{ToolContext,ToolType};
fn ctx(p:V)->ToolContext{ToolContext::new(p,Ray::new(V::new(0.5,0.5,10.),-V::Z))}
fn state(a:&IngeTrazoApp)->serde_json::Value{serde_json::json!({"origin":a.scene.image_planes[0].origin,"active":a.active_tool.snap_anchor().is_some(),"undo":a.undo_stack.len(),"redo":a.redo_stack.len(),"images":a.scene.image_planes.len()})}
fn main(){let mut rows=serde_json::Map::new();for case in ["selected","implicit","locked_implicit","locked_selected","hidden_selected","cancel","copy","fractional"]{let mut a=IngeTrazoApp::new();a.system_clipboard=None;let mut im=ImagePlane::new("missing",V::ZERO,V::X*2.,V::Y*2.);if case=="fractional"{im.origin=V::new(0.125,-1.25,2.5);}im.locked=case.starts_with("locked");if case=="hidden_selected"{im.layer=Some("Hidden".into());let mut layer=ingetrazo_core::layers::Layer::new("Hidden");layer.visible=false;a.scene.layers.push(layer);}a.scene.image_planes.push(im);if !["implicit","locked_implicit"].contains(&case){a.scene.select(SelectionItem::ImagePlane(0));}a.set_tool(ToolType::Move);let mut states=vec![state(&a)];a.dispatch_tool_click(&ctx(V::ZERO));states.push(state(&a));a.dispatch_tool_move(&ctx(if case=="fractional"{V::new(0.7,1.2,-0.3)}else{V::new(2.,3.,0.)}));states.push(state(&a));if case=="fractional"{a.dispatch_tool_move(&ctx(V::new(0.9,0.4,0.8)));states.push(state(&a));}if case=="copy"{a.active_tool.on_control_state(&mut a.scene,true);states.push(state(&a));}if case=="cancel"{a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));}else{let mut c=ctx(if case=="fractional"{V::new(0.6,0.8,-0.2)}else{V::new(4.,1.,0.)});c.ctrl_held=case=="copy";a.dispatch_tool_click(&c);states.push(state(&a));if !a.undo_stack.is_empty(){a.scene.image_planes[0].origin=(a.scene.image_planes[0].origin.as_vec3()+glam::Vec3::X*10.).as_dvec3();states.push(state(&a));a.undo();states.push(state(&a));a.redo();states.push(state(&a));}}rows.insert(case.into(),serde_json::json!(states));}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
